#include <bits/stdc++.h>
using namespace std; static const int NF=540,W=9;
struct Mask{array<uint64_t,W>w{};bool operator==(Mask const&o)const{return w==o.w;}};struct MH{size_t operator()(Mask const&m)const noexcept{uint64_t h=1469598103934665603ULL;for(auto x:m.w){h^=x;h*=1099511628211ULL;}return h;}};inline void sb(Mask&m,int x){m.w[x>>6]|=1ULL<<(x&63);}inline bool subset(const Mask&a,const Mask&b){for(int i=0;i<W;i++)if(a.w[i]&~b.w[i])return false;return true;}inline Mask subm(const Mask&a,const Mask&b){Mask c;for(int i=0;i<W;i++)c.w[i]=a.w[i]&~b.w[i];return c;}inline int pop(const Mask&m){int z=0;for(auto x:m.w)z+=__builtin_popcountll(x);return z;}Mask tf(const Mask&k,const vector<int>&g){Mask y;for(int wi=0;wi<W;wi++){uint64_t x=k.w[wi];while(x){int b=__builtin_ctzll(x);x&=x-1;int r=wi*64+b;if(r<NF)sb(y,g[r]);}}return y;}struct Sig{array<uint64_t,3>w{};bool operator==(Sig const&o)const{return w==o.w;}};struct SH{size_t operator()(Sig const&s)const noexcept{return s.w[0]^(s.w[1]*0x9e3779b97f4a7c15ULL)^(s.w[2]*0xbf58476d1ce4e5b9ULL);}};Sig packs(const array<int,45>&a){Sig s;for(int i=0;i<45;i++)s.w[i/16]|=(uint64_t)a[i]<<(4*(i%16));return s;}struct State{Mask rem;uint16_t sm;bool operator==(State const&o)const{return sm==o.sm&&rem==o.rem;}};struct StH{size_t operator()(State const&s)const noexcept{return MH{}(s.rem)^((uint64_t)s.sm*0x9e3779b97f4a7c15ULL);}};
struct Solver{vector<Mask>*covers;vector<vector<int>>*fib;array<int,9>sig;uint64_t nodes=0;double limit=300;bool timeout=false;chrono::steady_clock::time_point start;vector<int>sol;unordered_set<State,StH>dead;bool dfs(Mask rem,uint16_t sm){nodes++;if((nodes&0xffff)==0&&chrono::duration<double>(chrono::steady_clock::now()-start).count()>limit){timeout=true;return false;}int depth=__builtin_popcount((unsigned)sm);if(depth==0)return pop(rem)==0;if(pop(rem)!=60*depth)return false;State st{rem,sm};if(dead.count(st))return false;int bp=-1,bn=INT_MAX;vector<int>bc;for(int p=0;p<9;p++)if(sm&(1<<p)){vector<int>c;for(int ci:(*fib)[sig[p]])if(subset((*covers)[ci],rem))c.push_back(ci);if(c.empty()){dead.insert(st);return false;}if((int)c.size()<bn){bn=c.size();bp=p;bc.swap(c);}}uint16_t nsm=sm&~(1<<bp);for(int ci:bc){sol.push_back(ci);if(dfs(subm(rem,(*covers)[ci]),nsm))return true;sol.pop_back();if(timeout)return false;}dead.insert(st);return false;}};
int main(int argc,char**argv){if(argc!=8)return 2;double lim=atof(argv[7]);ifstream fi(argv[1]);int nr,ne,ng,z;fi>>nr>>ne>>ng;for(int i=0;i<nr*4;i++)fi>>z;vector<vector<int>>gens(ng,vector<int>(NF));for(auto&g:gens)for(int&i:g)fi>>i;vector<vector<int>>G;vector<int>id(NF);iota(id.begin(),id.end(),0);unordered_set<string>ps;auto pk=[](auto const&p){return string((char*)p.data(),p.size()*sizeof(int));};G.push_back(id);ps.insert(pk(id));for(size_t h=0;h<G.size();h++)for(auto&g:gens){vector<int>q(NF);for(int i=0;i<NF;i++)q[i]=g[G[h][i]];if(ps.insert(pk(q)).second)G.push_back(move(q));}ifstream rb(argv[2],ios::binary);uint64_t nrep;rb.read((char*)&nrep,8);vector<Mask>reps(nrep);for(size_t i=0;i<nrep;i++){for(int j=0;j<60;j++){uint16_t x;rb.read((char*)&x,2);sb(reps[i],x);}uint32_t q;rb.read((char*)&q,4);rb.read((char*)&q,4);rb.read((char*)&q,4);}unordered_set<Mask,MH>cs;for(auto&r:reps)for(auto&g:G)cs.insert(tf(r,g));vector<Mask>covers(cs.begin(),cs.end());vector<int>key(NF);{ifstream f(argv[3]);for(int&i:key)f>>i;}string ss;{ifstream f(argv[4]);ss.assign((istreambuf_iterator<char>(f)),{});}vector<array<int,45>>raw;vector<int>expect;size_t p=0;while((p=ss.find("\"count\":",p))!=string::npos){p+=8;expect.push_back(stoi(ss.substr(p)));p=ss.find("\"vector\":[",p)+10;array<int,45>a{};for(int q=0;q<45;q++){a[q]=stoi(ss.substr(p));p=ss.find(q==44?']':',',p)+1;}raw.push_back(a);}unordered_map<Sig,int,SH>sid;for(int i=0;i<720;i++)sid[packs(raw[i])]=i;vector<vector<int>>fib(720);for(int ci=0;ci<(int)covers.size();ci++){array<int,45>a{};for(int wi=0;wi<W;wi++){uint64_t x=covers[ci].w[wi];while(x){int b=__builtin_ctzll(x);x&=x-1;int f=wi*64+b;if(f<NF)a[key[f]]++;}}fib[sid.at(packs(a))].push_back(ci);}string ts;{ifstream f(argv[5]);ts.assign((istreambuf_iterator<char>(f)),{});}vector<array<int,9>>T;size_t tp=0;while((tp=ts.find('[',tp))!=string::npos){size_t q=tp+1;while(q<ts.size()&&isspace((unsigned char)ts[q]))q++;if(q>=ts.size()||!isdigit((unsigned char)ts[q])){tp++;continue;}array<int,9>t{};bool ok=true;for(int i=0;i<9;i++){while(q<ts.size()&&!isdigit((unsigned char)ts[q]))q++;if(q>=ts.size()){ok=false;break;}t[i]=stoi(ts.substr(q));q=ts.find(i==8?']':',',q);if(q==string::npos){ok=false;break;}q++;}if(ok)T.push_back(t);tp=q;}if(T.size()>6)T.erase(T.begin(),T.end()-6);Mask full;for(int i=0;i<NF;i++)sb(full,i);ofstream o(argv[6]);o<<"{\"results\":[";bool fst=1;int satn=0;for(int ti=0;ti<(int)T.size();ti++){Solver S;S.covers=&covers;S.fib=&fib;S.sig=T[ti];S.limit=lim;S.start=chrono::steady_clock::now();bool sat=S.dfs(full,(1<<9)-1);double sec=chrono::duration<double>(chrono::steady_clock::now()-S.start).count();satn+=sat;if(!fst)o<<",";fst=0;o<<"{\"tuple_index\":"<<ti<<",\"sat\":"<<(sat?"true":"false")<<",\"timeout\":"<<(S.timeout?"true":"false")<<",\"nodes\":"<<S.nodes<<",\"dead_states\":"<<S.dead.size()<<",\"seconds\":"<<fixed<<setprecision(6)<<sec<<"}";}o<<"],\"sat_tuples\":"<<satn<<",\"total\":"<<T.size()<<"}\n";}
